// src/plugin/provider/zenmux.ts
import { Effect } from "effect";
import { define } from "@opencode/plugin/effect/plugin";
var ZenmuxPlugin2 = define({
  id: "opencode.provider.zenmux",
  effect: Effect.fn(function* (ctx) {
    yield* ctx.provider.transform((evt) => {
      for (const item of evt.list()) {
        if (item.provider.package !== "@opencode/ai/providers/openai-compatible")
          continue;
        if (item.provider.settings?.baseURL !== "https://zenmux.ai/api/v1")
          continue;
        evt.update(item.provider.id, (provider) => {
          provider.headers = {
            "HTTP-Referer": "https://opencode.ai/",
            "X-Title": "opencode",
            ...provider.headers
          };
        });
      }
    });
  })
});

export { ZenmuxPlugin2 };
